entries[347411] = { ["name"] = "Sticky Muck", ["text"] = "40 yd range\nInstant\nThrow the muck at a location. All enemies within 8 yards will be slowed by 50% while in the area of effect. Trap will exist for 30 sec. Only usable outdoors in the Shadowlands." }
entries[347412] = { ["name"] = "Toss Soul Stalker Trap", ["text"] = "15 yd range\n1 sec cast 1 min cooldown\nPlace the trap within 15 yards of you. Enemies that walk over it have their movement slowed by 30% and take ( 131642 * 20 / 4) Shadow damage over 20 sec. Only usable outdoors in the Shadowlands." }
entries[347413] = { ["name"] = "Search for Lost Memories", ["text"] = "3 sec cast\nSearch the chronicle for lost memories, receiving a Memory of a legendary power for your class you do not already have." }
entries[347414] = { ["name"] = "Divide", ["text"] = "2 sec cast\nDivides the playspace into four sections with an additional barrier. Players are unable to target through the barriers." }
