entries[347417] = { ["name"] = "Infinite Rage", ["text"] = "1000 yd range\nInstant\nThreatening to take Timecap'n Hooktail's treasure sends her into a rage, stunning players for 5 sec while rewinding time, clearing all Storm Squalls and resetting the intensity of Winds of the Infinite.\n\nIncreases all damage done by Timecap'n Hooktail by 10%. This effect stacks." }
